/* Build the GitHub-Pages site. A standalone index.html with the raw WebGL2
 * renderer (the same modules as the inline single-file build, build.mjs) that
 * fetches its data from ./data/ (generated by `export_data.py --pages`). No 16MB
 * limit, so the full 1.3M-cell atlas is served (base.bin eager via a 100k lite
 * tier, genes lazy).
 *
 *   node viewer/build-pages.mjs    → pages/index.html
 */
import { readFileSync, writeFileSync, existsSync, cpSync, readdirSync, rmSync, mkdirSync, statSync } from "node:fs";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { gunzipSync, gzipSync } from "node:zlib";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, "src");
const read = (f) => readFileSync(join(SRC, f), "utf8");
// Raw WebGL2 renderer (gl.POINTS) — far faster + smoother than deck.gl's
// instanced-quad ScatterplotLayer for a 1.3M-point cloud. boot.js has a fetch-mode
// branch (window.__BIMP_SRC__) that loads the tiered base + lazy genes, so the same
// renderer that powers the inline artifact serves the full atlas here.
const MODULES = ["palette.js", "mat4.js", "shaders.js", "camera.js",
  "decode.js", "state.js", "renderer.js", "histology.js", "ui.js", "tour.js", "boot.js"];
// histology.js (the DAPI layer) is Pages-only: build.mjs leaves it out, so the artifact has no BIMP.histology.

// Favicon: Ian Traniello's drawing of the bee brain, traced with heavier lines so it holds at
// tab size (assets/favicon.svg), in a mid-grey that reads on light and dark tab bars alike. It is
// linked, not inlined: as a data: URI it put 36 KB in front of everything else in <head>. The PNGs
// in assets/icons (32 px tab fallback, 180 px apple-touch, 192/512 for the manifest) were rendered
// from it in headless Chrome, the large ones in ink on paper with a heavier stroke.

// Where the site is served (GitHub Pages). Link previews need absolute URLs.
const SITE = "https://kocherlab.github.io/bombus-impatiens-brain-atlas/";
const DESCRIPTION = "A bumble bee brain, cell by cell: 1,300,192 cells from the brains of a queen and a worker " +
  "of the common eastern bumble bee, each typed and placed back where it was, in 3D.";

// The webfonts ship with the site (assets/fonts: the Latin subsets only, ~135 KB, fetched once
// from Google Fonts), inlined as @font-face with font-display:block and the first screen's faces
// preloaded, so text never renders in a fallback face and then changes shape as fonts arrive.
const FONT_CSS = readFileSync(join(HERE, "assets", "fonts", "fonts.css"), "utf8");
const FONT_PRELOADS = ["alegreya-sans-400", "alegreya-sans-500", "alegreya-sans-800", "alegreya-sans-sc-500", "alegreya-400i"]
  .map((f) => `<link rel="preload" href="assets/fonts/${f}.woff2" as="font" type="font/woff2" crossorigin>`).join("\n");
const css = FONT_CSS + read("styles.css");
// The home page's brain is drawn by the atlas's own renderer, from a small HERO tier: about
// 20k real queen cells, every column the viewer uses, in the same binary layout as the lite
// and full tiers (so decode.js reads it unchanged). They are rows of the full atlas too, so
// when you enter, the viewer keeps exactly these cells on screen and grows the rest around them.
// It also carries every queen cell of ONE section, the one the home story cuts to (the middle of
// the queen's depth planes, as boot.js picks it), flagged in an extra column (hx). Phones never
// load the full tier, so without them that section held only the lite tier's ~2k of its ~24k
// cells; the renderer keeps them hidden until the story's section asks for them.
function hero(dataDir, liteIdx) {
  const mf = join(dataDir, "manifest.json");
  if (!existsSync(mf) || !liteIdx) return null;
  const M = JSON.parse(readFileSync(mf, "utf8"));
  let buf = readFileSync(join(dataDir, M.base));
  if (buf[0] === 0x1f && buf[1] === 0x8b) buf = gunzipSync(buf);
  const ab = new Uint8Array(buf.length); ab.set(buf);   // aligned, for the int16 view
  const cols = Object.entries(M.offsets).filter(([k]) => M.lite.offsets[k]);   // the lite tier's columns
  const C = new Uint8Array(ab.buffer, M.offsets.caste[0], M.n), Z = new Int16Array(ab.buffer, M.offsets.z[0], M.n);
  const inLite = new Uint8Array(M.n); for (const i of liteIdx) inLite[i] = 1;
  const zs = [...new Set(liteIdx.filter((i) => C[i] === 0).map((i) => Z[i]))].sort((a, b) => a - b), secZ = zs[zs.length >> 1];
  const rows = [], hx = [];
  for (let i = 0; i < M.n; i++) {
    if (C[i] !== 0) continue;
    if (inLite[i]) { rows.push(i); hx.push(0); } else if (Z[i] === secZ) { rows.push(i); hx.push(1); }
  }
  const n = rows.length, parts = [], offsets = {};
  let off = 0;
  for (const [name, [o, , t]] of cols) {
    const w = t === "int16" ? 2 : 1, src = Buffer.from(ab.buffer, o, M.n * w), dst = Buffer.alloc(n * w);
    rows.forEach((r, j) => src.copy(dst, j * w, r * w, r * w + w));
    offsets[name] = [off, n * w, t]; parts.push(dst); off += n * w;
  }
  offsets.hx = [off, n, "uint8"]; parts.push(Buffer.from(hx)); off += n;
  writeFileSync(join(dataDir, "base-hero.bin"), gzipSync(Buffer.concat(parts), { level: 9 }));
  // the drawn frame, front-on: the renderer shows stored (x, y) as (y, -x)
  const X = new Int16Array(Buffer.concat(parts).buffer.slice(offsets.x[0], offsets.x[0] + n * 2));
  const Y = new Int16Array(Buffer.concat(parts).buffer.slice(offsets.y[0], offsets.y[0] + n * 2));
  let w0 = Infinity, w1 = -Infinity, h0 = Infinity, h1 = -Infinity;
  for (let i = 0; i < n; i++) { w0 = Math.min(w0, Y[i]); w1 = Math.max(w1, Y[i]); h0 = Math.min(h0, -X[i]); h1 = Math.max(h1, -X[i]); }
  let nQueen = 0; for (let i = 0; i < M.n; i++) if (C[i] === 0) nQueen++;
  return { file: "base-hero.bin", n, offsets, gzip: true, secZ, baseBytes: statSync(join(dataDir, M.base)).size, nSection: hx.filter(Boolean).length, nQueen,
    regions: Object.fromEntries((M.regionDefs || []).map((d) => [d.key, d.bit])),
    // enough of the manifest for the renderer's region and subcluster colours on the home page,
    // before the atlas's own manifest has loaded
    regionDefs: (M.regionDefs || []).map((d) => ({ key: d.key, bit: d.bit })),
    ltkc: M.ltkc ? { colors: M.ltkc.colors } : null,
    canonColors: M.canonColors || null,   // the atlas's cell-type group colours, so the home brain matches it from the first frame
    box: [w0 / 32767, h0 / 32767, w1 / 32767, h1 / 32767], aspect: +((w1 - w0) / (h1 - h0)).toFixed(4) };
}

// The lite tier's place in the full one. base-lite.bin is a sorted row subset of base.bin, so
// matching them in order recovers each lite cell's full-tier index. Phones and weak devices
// draw the lite tier (boot.js deviceTier) and still colour it by any gene: a gene file holds
// every full-tier cell, and this index picks out the lite ones. Stored as Uint16 deltas (gzip).
function liteIndex(dataDir) {
  const mf = join(dataDir, "manifest.json");
  if (!existsSync(mf)) return null;
  const M = JSON.parse(readFileSync(mf, "utf8"));
  if (!M.lite || !existsSync(join(dataDir, M.base)) || !existsSync(join(dataDir, M.lite.file))) return null;
  const load = (f) => { let b = readFileSync(join(dataDir, f)); if (b[0] === 0x1f && b[1] === 0x8b) b = gunzipSync(b); return b; };
  const F = load(M.base), L = load(M.lite.file);
  const KEYS = ["x", "y", "z", "caste", "celltype", "conf"].filter((k) => M.offsets[k] && M.lite.offsets[k]);
  const col = (buf, off, n, k) => { const [o, , t] = off[k]; return t === "int16" ? new Int16Array(buf.buffer, buf.byteOffset + o, n) : new Uint8Array(buf.buffer, buf.byteOffset + o, n); };
  // int16 views need 2-byte alignment: copy into aligned buffers first
  const aligned = (b) => { const c = new Uint8Array(b.length); c.set(b); return c; };
  const Fa = aligned(F), La = aligned(L);
  const fc = KEYS.map((k) => col(Fa, M.offsets, M.n, k)), lc = KEYS.map((k) => col(La, M.lite.offsets, M.lite.n, k));
  const idx = new Uint32Array(M.lite.n);
  let i = 0;
  for (let j = 0; j < M.lite.n; j++) {
    for (; i < M.n; i++) { let ok = true; for (let c = 0; c < KEYS.length && ok; c++) ok = fc[c][i] === lc[c][j]; if (ok) break; }
    if (i >= M.n) { console.warn("⚠ lite tier is not an ordered subset of the full tier; no lite index written"); return null; }
    idx[j] = i++;
  }
  const d = new Uint16Array(M.lite.n);
  for (let j = 0, prev = -1; j < M.lite.n; j++) { const g = idx[j] - prev; if (g > 65535) { console.warn("⚠ lite index gap too large for Uint16"); return null; } d[j] = g; prev = idx[j]; }
  writeFileSync(join(dataDir, "base-lite.idx"), gzipSync(Buffer.from(d.buffer), { level: 9 }));
  return { file: "base-lite.idx", n: M.lite.n, of: M.version, idx };
}
const LITE_IDX = liteIndex(join(HERE, "pages", "data"));
const HERO = hero(join(HERE, "pages", "data"), LITE_IDX && Array.from(LITE_IDX.idx));
if (LITE_IDX) delete LITE_IDX.idx;
const heroBox = HERO && `<div id="hero-gl" style="aspect-ratio:${(HERO.aspect * 1.12).toFixed(3)}" ` +
  `role="img" aria-label="The queen brain, one dot per cell, turning slowly">` +
  // the axis triad: turned each frame by boot.js from the renderer's own camera
  `<svg class="triad" aria-hidden="true" viewBox="-60 -50 120 100"><g></g></svg></div>`;
// Ian Traniello's labelled mushroom-body close-up (93 KB) is not inlined here: intro-stipple.js
// fetches it as the Anatomy section nears and inlines it then, so its labels still use the
// page's webfonts (an SVG loaded as an image cannot see them).
const body0 = HERO
  ? read("body.html").replace(/<div id="intro-art">[\s\S]*?<\/div>/, `<div id="intro-art">${heroBox}</div>`)
  : read("body.html");
const body1 = body0;
// the hero tier's layout rides inline; its bytes are preloaded beside the page
const introArt = (HERO ? `<script>window.__BIMP_HERO__ = ${JSON.stringify(HERO)};</script>\n` : "") +
  (LITE_IDX ? `<script>window.__BIMP_LITE_IDX__ = ${JSON.stringify(LITE_IDX)};</script>\n` : "") +
  `<script>\n${read("intro-stipple.js")}\n</script>\n`;
// The atlas code (~240 KB) ships as ONE external file named by its content hash, not inline: the
// browser can cache it (and keep V8's compiled code) across visits, the page's own bytes shrink
// by two thirds, and intro-stipple.js runs it only once the first screen has painted, so the
// renderer's WebGL setup can never hold the text back. The hash in the name means a deploy is
// never half-cached: GitHub Pages serves everything with max-age=600, the page included.
const ATLAS_JS = MODULES.map((m) => `/* ---- ${m} ---- */\n${read(m)}\n;`).join("\n");
const ATLAS = `assets/atlas.${createHash("sha256").update(ATLAS_JS).digest("hex").slice(0, 10)}.js`;

const html = `<!doctype html>
<html lang="en" class="pages">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Bombus impatiens brain atlas — a bumble bee brain, cell by cell</title>
<meta name="description" content="${DESCRIPTION}">
<link rel="canonical" href="${SITE}">
<meta name="theme-color" content="#f4ecdc">
<script>
/* which view the page opens in, before anything paints; the browser bar follows it (paper on
   the home page, the stage's black in the atlas) */
(function () {
  var r = document.documentElement, t = document.querySelector('meta[name="theme-color"]');
  r.dataset.view = /[?&](nointro|atlas|tour)(=|&|$)/.test(location.search) ? "atlas" : "home";
  // a link straight into the atlas: hold the controls until the cells start to appear (boot.js)
  if (r.dataset.view === "atlas") r.classList.add("atlas-boot");
  var sync = function () { t.content = /atlas/.test(r.dataset.view || "") ? "#0b0b0a" : "#f4ecdc"; };
  sync(); new MutationObserver(sync).observe(r, { attributes: true, attributeFilter: ["data-view"] });
  // the hero's cells are only needed when the page opens on home; a link into the atlas skips them
  ${HERO ? `if (r.dataset.view === "home") { var l = document.createElement("link"); l.rel = "preload"; l.href = "data/base-hero.bin"; l.as = "fetch"; l.crossOrigin = "anonymous"; l.setAttribute("fetchpriority", "low"); document.head.appendChild(l); }` : ""}
})();
</script>
${FONT_PRELOADS}
<link rel="preload" href="${ATLAS}" as="script" fetchpriority="low">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml">
<link rel="icon" href="assets/icons/favicon-32.png" type="image/png" sizes="32x32">
<link rel="apple-touch-icon" href="assets/icons/apple-touch-icon.png">
<link rel="manifest" href="assets/site.webmanifest">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Bombus impatiens brain atlas">
<meta property="og:title" content="A bumble bee brain, cell by cell">
<meta property="og:description" content="${DESCRIPTION}">
<meta property="og:url" content="${SITE}">
<meta property="og:image" content="${SITE}assets/og.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="The bumble bee brain atlas home page: the queen brain drawn as one dot per cell beside the title">
<meta name="twitter:card" content="summary_large_image">
<style>
${css}
</style>
</head>
<body>
${body1}
<script>window.__BIMP_SRC__ = "./data/"; window.__BIMP_ATLAS__ = "${ATLAS}";</script>
${introArt}</body>
</html>
`;

if (!existsSync(join(HERE, "pages", "data", "manifest.json"))) {
  console.warn("⚠ pages/data/manifest.json missing — run: PYTHONPATH=src .venv/bin/python viewer/export_data.py --pages");
}
// Wenfei Tong's drawings (ink-only, via tools/ink-drawings.mjs) and Ian Traniello's brain
// drawing ship beside the page; the home page's drawing sections show only in this build (html.pages).
cpSync(join(HERE, "assets", "drawings"), join(HERE, "pages", "assets", "drawings"), { recursive: true });
cpSync(join(HERE, "assets", "fonts"), join(HERE, "pages", "assets", "fonts"), { recursive: true });
cpSync(join(HERE, "assets", "brain-schematic.svg"), join(HERE, "pages", "assets", "brain-schematic.svg"));
cpSync(join(HERE, "assets", "mushroom-body-zoom.svg"), join(HERE, "pages", "assets", "mushroom-body-zoom.svg"));
cpSync(join(HERE, "assets", "mushroom-body-labelled.svg"), join(HERE, "pages", "assets", "mushroom-body-labelled.svg"));
// the shell: favicon + icons, the web manifest, the link-preview image (a 1200x630 capture of the
// home page's first screen)
cpSync(join(HERE, "assets", "favicon.svg"), join(HERE, "pages", "assets", "favicon.svg"));
cpSync(join(HERE, "assets", "icons"), join(HERE, "pages", "assets", "icons"), { recursive: true });
cpSync(join(HERE, "assets", "site.webmanifest"), join(HERE, "pages", "assets", "site.webmanifest"));
cpSync(join(HERE, "assets", "og.png"), join(HERE, "pages", "assets", "og.png"));
cpSync(join(HERE, "assets", "kocherlab-logo.png"), join(HERE, "pages", "assets", "kocherlab-logo.png"));   // the footer's lab logo (kocherlab.berkeley.edu)
// the atlas bundle, and no stale ones beside it
mkdirSync(join(HERE, "pages", "assets"), { recursive: true });
for (const f of readdirSync(join(HERE, "pages", "assets")))
  if (/^atlas\.[0-9a-f]+\.js$/.test(f) && `assets/${f}` !== ATLAS) rmSync(join(HERE, "pages", "assets", f));
writeFileSync(join(HERE, ATLAS.replace(/^assets/, "pages/assets")), ATLAS_JS);
// tools/sections-figure.mjs writes this strip (and the tile grid in body.html that windows onto it)
cpSync(join(HERE, "assets", "sections.webp"), join(HERE, "pages", "assets", "sections.webp"));
const out = join(HERE, "pages", "index.html");
writeFileSync(out, html);
console.log(`✓ wrote ${out}  (raw WebGL2 renderer; data served from pages/data/)`);
